namespace Store;

public sealed class ShoppingCart
{
    private readonly Dictionary<string, (int Quantity, decimal Price)> _items = new();
    private decimal _discountPercent;

    public void AddItem(string sku, int quantity, decimal price)
    {
        if (string.IsNullOrEmpty(sku))
            throw new ArgumentException("SKU cannot be null or empty.", nameof(sku));
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be greater than zero.");
        if (price < 0)
            throw new ArgumentOutOfRangeException(nameof(price), "Price cannot be negative.");

        if (_items.TryGetValue(sku, out var existing))
        {
            _items[sku] = (existing.Quantity + quantity, price);
        }
        else
        {
            _items[sku] = (quantity, price);
        }
    }

    public void RemoveItem(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            throw new ArgumentException("SKU cannot be null or empty.", nameof(sku));
        if (!_items.Remove(sku))
            throw new KeyNotFoundException($"SKU '{sku}' not found in cart.");
    }

    public decimal CalculateTotal()
    {
        if (_items.Count == 0)
            return 0m;

        decimal subtotal = 0m;
        foreach (var item in _items.Values)
        {
            subtotal += item.Quantity * item.Price;
        }

        return subtotal - (subtotal * _discountPercent / 100m);
    }

    public void ApplyCoupon(string code)
    {
        if (string.IsNullOrEmpty(code))
            throw new ArgumentException("Coupon code cannot be null or empty.", nameof(code));

        _discountPercent = code switch
        {
            "SAVE10" => 10m,
            "SAVE20" => 20m,
            _ => throw new ArgumentException($"Unknown coupon code '{code}'.", nameof(code))
        };
    }
}

using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // ── AddItem: happy path ──

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 9.99m);

        // Assert
        Assert.AreEqual(19.98m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_AllIncludedInTotal()
    {
        // Arrange & Act
        _cart.AddItem("A", 1, 10.00m);
        _cart.AddItem("B", 3, 5.00m);

        // Assert
        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_QuantityAccumulates()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-001", 3, 10.00m);

        // Assert – quantity should be 5 * 10 = 50
        Assert.AreEqual(50.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwiceWithDifferentPrice_UsesLatestPrice()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-001", 1, 20.00m);

        // Assert – quantity 3, latest price 20 => 60
        Assert.AreEqual(60.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Allowed()
    {
        // Arrange & Act
        _cart.AddItem("FREE", 5, 0.00m);

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    // ── AddItem: validation ──

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void AddItem_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        // Act & Assert
        var ex = Assert.ThrowsException<ArgumentException>(() => _cart.AddItem(sku!, 1, 10.00m));
        Assert.AreEqual("sku", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_ThrowsArgumentOutOfRangeException(int quantity)
    {
        // Act & Assert
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", quantity, 10.00m));
        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        // Act & Assert
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", 1, -5.00m));
        Assert.AreEqual("price", ex.ParamName);
    }

    // ── RemoveItem: happy path ──

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovedFromTotal()
    {
        // Arrange
        _cart.AddItem("A", 1, 10.00m);
        _cart.AddItem("B", 1, 20.00m);

        // Act
        _cart.RemoveItem("A");

        // Assert
        Assert.AreEqual(20.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_OnlyItem_CartBecomesEmpty()
    {
        // Arrange
        _cart.AddItem("A", 2, 15.00m);

        // Act
        _cart.RemoveItem("A");

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    // ── RemoveItem: error cases ──

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFoundException()
    {
        // Act & Assert
        Assert.ThrowsException<KeyNotFoundException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void RemoveItem_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        // Act & Assert
        var ex = Assert.ThrowsException<ArgumentException>(() => _cart.RemoveItem(sku!));
        Assert.AreEqual("sku", ex.ParamName);
    }

    // ── CalculateTotal ──

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        // Act & Assert
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterAddAndRemoveAll_ReturnsZero()
    {
        // Arrange
        _cart.AddItem("A", 1, 10.00m);
        _cart.RemoveItem("A");

        // Act & Assert
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfQuantityTimesPrice()
    {
        // Arrange
        _cart.AddItem("A", 2, 10.00m);  // 20
        _cart.AddItem("B", 1, 5.50m);   // 5.50
        _cart.AddItem("C", 3, 3.00m);   // 9.00

        // Act
        var total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(34.50m, total);
    }

    // ── ApplyCoupon: happy path ──

    [TestMethod]
    public void ApplyCoupon_Save10_Applies10PercentDiscount()
    {
        // Arrange
        _cart.AddItem("A", 1, 100.00m);

        // Act
        _cart.ApplyCoupon("SAVE10");

        // Assert
        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Save20_Applies20PercentDiscount()
    {
        // Arrange
        _cart.AddItem("A", 1, 100.00m);

        // Act
        _cart.ApplyCoupon("SAVE20");

        // Assert
        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_OnEmptyCart_TotalRemainsZero()
    {
        // Act
        _cart.ApplyCoupon("SAVE10");

        // Assert
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_LatestCouponWins()
    {
        // Arrange
        _cart.AddItem("A", 1, 100.00m);

        // Act – apply two coupons; latest should win
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        // Assert – 20% off 100 = 80
        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Save10_CorrectWithMultipleItems()
    {
        // Arrange
        _cart.AddItem("A", 2, 50.00m);  // 100
        _cart.AddItem("B", 1, 25.00m);  // 25
        // subtotal = 125

        // Act
        _cart.ApplyCoupon("SAVE10");

        // Assert – 125 - 12.50 = 112.50
        Assert.AreEqual(112.50m, _cart.CalculateTotal());
    }

    // ── ApplyCoupon: error cases ──

    [TestMethod]
    [DataRow(null, DisplayName = "Null code")]
    [DataRow("", DisplayName = "Empty code")]
    public void ApplyCoupon_NullOrEmptyCode_ThrowsArgumentException(string? code)
    {
        // Act & Assert
        var ex = Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(code!));
        Assert.AreEqual("code", ex.ParamName);
    }

    [TestMethod]
    [DataRow("INVALID", DisplayName = "Unknown code")]
    [DataRow("save10", DisplayName = "Lowercase variant")]
    [DataRow("SAVE30", DisplayName = "Unsupported percentage")]
    public void ApplyCoupon_UnknownCode_ThrowsArgumentException(string code)
    {
        // Act & Assert
        var ex = Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(code));
        Assert.AreEqual("code", ex.ParamName);
    }

    // ── Integration / combined scenarios ──

    [TestMethod]
    public void FullWorkflow_AddItemsApplyCouponRemoveItem_CorrectTotal()
    {
        // Arrange
        _cart.AddItem("A", 2, 10.00m);  // 20
        _cart.AddItem("B", 1, 30.00m);  // 30
        _cart.ApplyCoupon("SAVE10");     // 10% off

        // Act
        _cart.RemoveItem("A");           // remove 20 worth
        var total = _cart.CalculateTotal();

        // Assert – subtotal 30, 10% off = 27
        Assert.AreEqual(27.00m, total);
    }

    [TestMethod]
    public void AddItem_ThenRemove_ThenReAdd_CorrectTotal()
    {
        // Arrange
        _cart.AddItem("A", 1, 10.00m);
        _cart.RemoveItem("A");

        // Act
        _cart.AddItem("A", 3, 5.00m);

        // Assert
        Assert.AreEqual(15.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_AlreadyRemoved_ThrowsKeyNotFoundException()
    {
        // Arrange
        _cart.AddItem("A", 1, 10.00m);
        _cart.RemoveItem("A");

        // Act & Assert
        Assert.ThrowsException<KeyNotFoundException>(() => _cart.RemoveItem("A"));
    }
}

