14.         if (price < 0)
15.             throw new ArgumentOutOfRangeException(nameof(price), "Price cannot be negative.");
16. 
17.         if (_items.TryGetValue(sku, out var existing))
18.         {
19.             _items[sku] = (existing.Quantity + quantity, price);
20.         }
